// Pix "copia e cola" estático (BR Code / EMV) para um agendamento da PataCerta.
// O valor vem do serviço do agendamento na API, nunca do chamador.
const body = $('Webhook Pix').first().json.body || {};
const fail = (erro) => [{ json: { ok: false, erro } }];

const key = ($env.PIX_KEY || '').trim();
if (!key) return fail('O Pix da clínica ainda não foi configurado.');

// A lista chega como um item por agendamento; se a API recusar o token, chega um item de erro.
const list = $input.all().map((i) => i.json);
if (list.some((a) => a.error)) return fail('Sessão inválida ou expirada. Entre novamente.');
const appt = list.find((a) => a.id === body.agendamento_id);
if (!appt) return fail('Agendamento não encontrado.');
if (appt.status === 'CANCELED') return fail('Esse agendamento foi cancelado.');
const cents = appt.service && appt.service.priceCents;
if (!Number.isInteger(cents) || cents <= 0) return fail('Esse serviço não tem valor cadastrado.');

const ascii = (s, max) =>
  String(s).normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^A-Za-z0-9 ]/g, '').toUpperCase().trim().slice(0, max);
const field = (id, value) => id + String(value.length).padStart(2, '0') + value;

const amount = (cents / 100).toFixed(2);
const txid = 'PC' + appt.id.replace(/-/g, '').slice(0, 23);
const payload =
  field('00', '01') +
  field('26', field('00', 'br.gov.bcb.pix') + field('01', key)) +
  field('52', '0000') +
  field('53', '986') +
  field('54', amount) +
  field('58', 'BR') +
  field('59', ascii($env.PIX_RECEIVER_NAME || 'PataCerta', 25) || 'PATACERTA') +
  field('60', ascii($env.PIX_CITY || 'Recife', 15) || 'RECIFE') +
  field('62', field('05', txid)) +
  '6304';

let crc = 0xffff;
for (let i = 0; i < payload.length; i++) {
  crc ^= payload.charCodeAt(i) << 8;
  for (let b = 0; b < 8; b++) crc = crc & 0x8000 ? ((crc << 1) ^ 0x1021) & 0xffff : (crc << 1) & 0xffff;
}

const valor = (cents / 100).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
const pet = appt.pet && appt.pet.name;
const servico = appt.service && appt.service.name;
return [
  {
    json: {
      ok: true,
      valor,
      descricao: servico + (pet ? ' de ' + pet : ''),
      pix_copia_e_cola: payload + crc.toString(16).toUpperCase().padStart(4, '0'),
    },
  },
];
